#!/usr/bin/env bash
# install.sh — reproduce this Arch setup on a NEW machine.
#
# SELF-CONTAINED: the package lists, every dotfile and the GNOME dconf dump are
# embedded in this file. Copy this one file to a new box and run it — no git
# clone, no other files needed.
#
#   ./install.sh              # do it
#   ./install.sh --dry-run    # print every action, change nothing
#
# Run as your normal user (NOT root). Uses sudo per-command; makepkg refuses root.
#
# DO NOT EDIT THIS FILE — it is generated by capture.sh from install-template.sh
# plus the contents of packages/, dotfiles/ and dconf/. Edit the template.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

DRY=0
for a in "$@"; do
  case "$a" in
    --dry-run|-n) DRY=1 ;;
    -h|--help)
      cat <<'USAGE'
install.sh — reproduce this Arch setup on a new machine.

  ./install.sh              install everything
  ./install.sh --dry-run    print every action, change nothing
  ./install.sh --help       this text

Self-contained: packages, dotfiles and GNOME settings are embedded in this
file. Run it as your normal user, not root.

Environment:
  ARCH_SETUP_DIR   where embedded files are unpacked
                   (default ~/.local/share/arch-setup)
USAGE
      exit 0 ;;
    *) printf 'unknown argument: %s (try --help)\n' "$a" >&2; exit 1 ;;
  esac
done

say()  { printf '\033[1;34m::\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m!!\033[0m %s\n' "$*" >&2; }
run()  { if (( DRY )); then printf '\033[2m[dry] %s\033[0m\n' "$*"; else eval "$*"; fi; }

[[ $EUID -eq 0 ]] && { warn "Do not run as root. Run as your user; sudo is used where needed."; exit 1; }
command -v pacman >/dev/null || { warn "Not an Arch system (no pacman)."; exit 1; }

# --- BEGIN EMBEDDED PAYLOAD — generated by capture.sh, do not edit ---
_dir() { mkdir -p "$ROOT/$1"; }
# _file <relpath> <strip-trailing-newline>  — content arrives on stdin.
# A heredoc always ends in a newline; files captured without one are trimmed
# back so the unpacked copy is byte-identical to the original.
_file() {
  local rel="$1" strip="${2:-0}"
  mkdir -p "$ROOT/$(dirname "$rel")"
  cat > "$ROOT/$rel"
  if (( strip )); then truncate -s -1 "$ROOT/$rel"; fi
  return 0
}
